public class Solution
{
    public int Jump(int[] nums)
    {
        // Raj Thomas 30th May 2026 1:56PM IST
        // Top Down Approach

        int[] dp = new int[nums.Length];
        Array.Fill(dp, -1);

        helper(nums, 0, dp);

        return dp[0];
    }

    private int helper(int[] nums, int idx, int[] dp) {

        if(idx >= nums.Length - 1) {
            dp[nums.Length - 1] = 0;
            return dp[nums.Length - 1];
        }

        if(dp[idx] != -1) return dp[idx];

        int result = int.MaxValue;
        for(int jump = 1; jump <= nums[idx] && idx + jump < nums.Length; jump++) {

            int next = helper(nums, idx + jump, dp);

            if(next != int.MaxValue)
                result = Math.Min(result, next + 1);
        }

        dp[idx] = result;
        return result;
    }
}

```

